"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "../lib/cn.js";
import { overlay } from "../motion/index.js";

// Generated by shadcn (Base UI, Mira) and rewritten: an `ink` label with `on-ink` text (15:1),
// `--radius-field`, no arrow. It keeps Base UI's hover delay, appears over `--dur-quick` by
// opacity and a small scale (M9), and only fades under reduced motion (M10).

export const TooltipProvider = TooltipPrimitive.Provider;
export const Tooltip = TooltipPrimitive.Root;
export const TooltipTrigger = TooltipPrimitive.Trigger;

export function TooltipContent({
  className,
  side = "top",
  sideOffset = overlay.floatOffset,
  align = "center",
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "align" | "side" | "sideOffset">) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        className="z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={cn(
            "inline-flex max-w-xs items-center gap-2 rounded-field bg-ink px-2.5 py-1.5",
            "font-sans text-sm font-medium text-on-ink shadow-lift",
            "origin-(--transform-origin) transition-[opacity,scale] duration-(--dur-quick) ease-out",
            "data-starting-style:scale-(--enter-float-scale) data-starting-style:opacity-0",
            "data-ending-style:opacity-0 data-instant:transition-none",
            "motion-reduce:data-starting-style:scale-100",
            typeof className === "string" ? className : undefined,
          )}
          {...props}
        />
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}
